            CONSTRAINT [FK_LichSuHoanTien_NguoiXuLy] FOREIGN KEY ([NguoiXuLyId])
                REFERENCES [dbo].[NguoiDung]([Id]) ON DELETE NO ACTION,
            CONSTRAINT [CK_LichSuHoanTien_SoTien] CHECK ([SoTien] > 0)
