    IF NOT EXISTS (SELECT 1 FROM [dbo].[DanhMuc] WHERE [TenDanhMuc] = N'Nhac song')
        INSERT INTO [dbo].[DanhMuc] ([TenDanhMuc], [MoTa], [Icon], [ThuTu], [TrangThai])
