        VALUES (N'The thao', N'Cac su kien the thao, giai dau, thi dau', N'⚽', 3, 1);

    IF NOT EXISTS (SELECT 1 FROM [dbo].[DanhMuc] WHERE [TenDanhMuc] = N'Hoi thao & Workshop')
