INSERT INTO dbo.VeDienTu
    (Id, ChiTietDonHangId, MaVe, MaQRCode, DuongDanQR, TrangThai, NgayTao)
VALUES
    ('52000000-0000-0000-0000-000000000024', @OrderDetailId024, 'TK26000024', 'QR-WE2026-000024', NULL, 0, '2026-06-16T13:24:00');


    UPDATE lv
    SET SoLuongDaBan = sold.Quantity
    FROM dbo.LoaiVe lv
    JOIN (
        SELECT ct.LoaiVeId, COUNT(*) AS Quantity
        FROM dbo.ChiTietDonHang ct
        JOIN dbo.DonHang dh ON dh.Id = ct.DonHangId
        WHERE dh.TrangThai = 1
        GROUP BY ct.LoaiVeId
    ) sold ON sold.LoaiVeId = lv.Id;

    IF OBJECT_ID('dbo.LichSuSoDu') IS NOT NULL
    BEGIN
        INSERT INTO dbo.LichSuSoDu (OrganizerId, LoaiGiaoDich, SoTien, SoDuSauGD, NoiDung, NgayTao)
        SELECT
            sk.NguoiToChucId,
            0,
            SUM(dh.TongTienVe - dh.TienGiamGia - CASE WHEN sk.AiChiuPhi = 1 THEN dh.PhiDichVu ELSE 0 END),
            SUM(dh.TongTienVe - dh.TienGiamGia - CASE WHEN sk.AiChiuPhi = 1 THEN dh.PhiDichVu ELSE 0 END),
            N'Doanh thu ban đầu từ professional seed',
            GETUTCDATE()
        FROM dbo.DonHang dh
        JOIN dbo.SuKien sk ON sk.Id = dh.SuKienId
        WHERE dh.TrangThai = 1
        GROUP BY sk.NguoiToChucId;
    END

    IF OBJECT_ID('dbo.SoDuOrganizer') IS NOT NULL
    BEGIN
        UPDATE balance
        SET SoDuKhaDung = balance.SoDuKhaDung + revenue.NetRevenue,
            NgayCapNhat = GETUTCDATE()
        FROM dbo.SoDuOrganizer balance
        JOIN (
            SELECT
                sk.NguoiToChucId AS OrganizerId,
                SUM(dh.TongTienVe - dh.TienGiamGia - CASE WHEN sk.AiChiuPhi = 1 THEN dh.PhiDichVu ELSE 0 END) AS NetRevenue
            FROM dbo.DonHang dh
            JOIN dbo.SuKien sk ON sk.Id = dh.SuKienId
            WHERE dh.TrangThai = 1
            GROUP BY sk.NguoiToChucId
        ) revenue ON revenue.OrganizerId = balance.OrganizerId;
    END

    INSERT INTO dbo.CauHinhHeThong (MaCauHinh, GiaTri, MoTa, NgayCapNhat)
    VALUES
        ('VNPay_TmnCode', '', N'Mã terminal VNPay', GETUTCDATE()),
        ('VNPay_HashSecret', '', N'Secret key VNPay', GETUTCDATE()),
        ('VNPay_Url', 'https://sandbox.vnpayment.vn/paymentv2/vpcpay.html', N'URL thanh toán VNPay', GETUTCDATE()),
        ('VNPay_ReturnUrl', 'http://localhost:5127/Booking/PaymentReturn', N'URL trả về sau thanh toán VNPay', GETUTCDATE()),
        ('Email_SmtpHost', 'smtp.gmail.com', N'SMTP host gửi email', GETUTCDATE()),
        ('Email_SmtpPort', '587', N'SMTP port gửi email', GETUTCDATE()),
        ('Email_Username', '', N'Email dùng để gửi', GETUTCDATE()),
        ('Email_Password', '', N'Mật khẩu email gửi', GETUTCDATE());

    COMMIT TRANSACTION;
    PRINT N'Professional WuangEvents seed completed: 6 categories, 72 events, local cover images.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    THROW;
END CATCH;
GO

